mapper.sql:
where d.document_type = 'textbook' and d.del_flag = '0'
and d.create_by = #{visibleUserId}
and d.certification_id = #{certificationId}
and d.syllabus_version_id = #{syllabusVersionId}
and d.create_by = #{createBy}
and d.title ilike concat('%', #{query.title}, '%')
and d.edition ilike concat('%', #{query.edition}, '%')
and d.status = #{query.status}
and d.create_time between #{query.beginCreateTime} and #{query.endCreateTime}

mapper.select:
select count(*) from cm_chunk_knowledge ck
join cm_document_chunk chunk on chunk.id = ck.chunk_id
where chunk.document_id = #{documentId}

select es.id from cm_document d
join cm_exam_subject es on es.certification_id = d.certification_id
where d.id = #{documentId} and es.id = #{examSubjectId}

select  from cm_document_chunk c 
where c.document_id = #{documentId} 
order by c.chunk_order asc limit #{limit} offset #{offset}

mapper.update:
update cm_document_chunk set heading = #{heading}, content = #{content}, content_hash = #{contentHash},
    update_by = #{userId}, update_time = now()
where id = #{chunkId} and document_id = #{documentId} and update_time = #{updateTime}

